<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from 'vue'
import { processingApi, poolLabels, executionLabels, type AdminProcessing, type Limits } from '../services/processing'
const state = ref<AdminProcessing>(); const draft = ref<Limits>(); const error = ref(''); const saving = ref(false); const page = ref(1); let timer = 0; let alive = true; let draftRevision = 0
async function load(reset = false) { try { state.value = await processingApi.admin(page.value); if (!draft.value || reset) { draft.value = JSON.parse(JSON.stringify(state.value.resources.config.limits)); draftRevision = state.value.resources.config.revision } if (reset) error.value = '' } catch (cause) { error.value = String(cause) } }
async function save() { if (!draft.value || !state.value) return; saving.value = true; try { await processingApi.config(draft.value, draftRevision); await load(true) } catch (cause) { error.value = String(cause) } finally { saving.value = false } }
async function poll() { await load(); if (alive) timer = window.setTimeout(poll, 3000) }
onMounted(poll); onBeforeUnmount(() => { alive = false; clearTimeout(timer) })
</script>
<template><header class="page-heading"><div><h1>任务与资源管理</h1><p>查看全局积压与账户瓶颈。降低容量不会中止正在运行的任务。</p></div></header><a-alert v-if="error" type="error" :message="error" show-icon /><section v-if="state && draft" class="processing-admin"><a-descriptions title="正在运行" bordered><a-descriptions-item v-for="pool in ['CPU','RECOGNITION','GENERATION']" :key="pool" :label="poolLabels[pool]">{{ state.resources.running[pool] || 0 }}</a-descriptions-item></a-descriptions><a-form layout="vertical" @finish="save"><div class="limits-grid"><a-form-item label="本地处理容量"><a-input-number v-model:value="draft.cpu" :min="1" :max="16" /></a-form-item><a-form-item label="识别容量"><a-input-number v-model:value="draft.recognition" :min="1" :max="32" /></a-form-item><a-form-item label="增强容量"><a-input-number v-model:value="draft.generation" :min="1" :max="16" /></a-form-item><a-form-item label="每个上游凭据账户总并发"><a-input-number v-model:value="draft.accountConcurrency" :min="1" :max="64" /></a-form-item><a-form-item label="助手预留并发"><a-input-number v-model:value="draft.assistantReserved" :min="0" :max="draft.accountConcurrency" /></a-form-item><a-form-item label="每分钟请求数 RPM（未知时留空）"><a-input-number v-model:value="draft.rpm" :min="1" /></a-form-item></div><a-form-item label="暂停资源池"><a-checkbox-group v-model:value="draft.paused" :options="Object.entries(poolLabels).map(([value,label]) => ({ value, label }))" /></a-form-item><a-button type="primary" html-type="submit" :loading="saving">保存调度配置</a-button><a-button @click="load(true)">重新读取配置</a-button></a-form><h2>全局积压</h2><div v-for="(count,i) in state.resources.counts" :key="i">{{ poolLabels[String(count.POOL || count.pool)] }} · {{ executionLabels[String(count.STATUS || count.status)] }}：{{ count.TOTAL ?? count.total }}</div><h2>账户占用</h2><p v-if="!state.resources.accounts.length">当前没有上游请求占用。</p><p v-for="(account,i) in state.resources.accounts" :key="i">{{ account.ACCOUNT_ID || account.account_id }} · {{ account.PURPOSE || account.purpose }} · {{ account.STATUS || account.status }}：{{ account.TOTAL ?? account.total }}</p><h2>最近任务</h2><article v-for="task in state.items" :key="task.id" class="admin-task"><strong>{{ task.owner || '旧任务' }} · {{ poolLabels[task.pool] }} · {{ executionLabels[task.status] }}</strong><p>{{ task.waitReason || task.error || task.businessId }}</p></article><a-space><a-button :disabled="page === 1" @click="page--; load()">上一页</a-button><span>第 {{ page }} 页</span><a-button :disabled="state.items.length < 100" @click="page++; load()">下一页</a-button></a-space></section></template>
<style scoped>.processing-admin{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:24px}.processing-admin h2{margin:24px 0 12px}.processing-admin form{margin-top:24px}.limits-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px}.admin-task{padding:12px 0;border-bottom:1px solid var(--line)}.admin-task p{color:var(--muted);margin-top:6px}</style>
